class Solution {
    public int minimumSum(int n, int k) {
        int m = Math.min(n, k / 2);
        int rem = n - m;
        int sum1 = m * (m + 1) / 2;
        int sum2 = rem * k + rem * (rem - 1) / 2;
        return sum1 + sum2;
    }
}

/**
