 * @param {number} k
 * @return {number}
 */
var minimumSum = function(n, k) {
    const m = Math.min(n, Math.floor(k / 2));
    const rem = n - m;
    const sum1 = Math.floor(m * (m + 1) / 2);
    const sum2 = rem * k + Math.floor(rem * (rem - 1) / 2);
    return sum1 + sum2;
};
